theme.css:
/* theme: Scandal Ticker | A wire-ticker page for a day when a chipmaker's fall, a wartime warning, and market slips all run on the same red tape. */
/* mood: bad */
/* layout: hero=centered; major-events=banner/grid-2; political-news=plain/stack; financial-news=stat/stack; tech-news=outline/grid-2; entertainment-news=numbered/masonry; sports=split/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=timeline/stack */

.diary-page {
  --paper: #1c0b0d;
  --paper-alt: #2a1013;
  --ink: #f7e8e2;
  --ink-soft: #d9c8c2;
  --muted: #a89a94;
  --accent: #ff5c5c;
  --accent-ink: #1a0808;
  --rule: #4a2a2e;
  --font-display: var(--ff-unbounded), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;

  background:
    linear-gradient(180deg, transparent 0%, transparent 48%, rgba(255, 92, 92, 0.06) 48%, rgba(255, 92, 92, 0.06) 49%, transparent 49%, transparent 100%),
    linear-gradient(90deg, transparent 0%, transparent 98%, rgba(255, 92, 92, 0.05) 98%, rgba(255, 92, 92, 0.05) 100%, transparent 100%),
    var(--paper);
}

/* Header: centered, with a red ticker tape band running behind the title */
.diary-page[data-hero="centered"] .diary-hero {
  background: var(--paper-alt);
  border-bottom: 1px solid var(--rule);
  position: relative;
  overflow: hidden;
}

.diary-page[data-hero="centered"] .diary-hero::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 0.35rem;
  background: repeating-linear-gradient(
    90deg,
    var(--accent) 0rem,
    var(--accent) 1.5rem,
    transparent 1.5rem,
    transparent 3.5rem
  );
}

.diary-page[data-hero="centered"] .diary-hero-inner {
  text-align: center;
  padding-top: 2.5rem;
}

.diary-page[data-hero="centered"] .diary-title {
  margin-inline: auto;
  font-size: clamp(2.25rem, 6vw, 4.75rem);
  font-weight: 800;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  line-height: 1.05;
  max-width: 14ch;
  color: var(--ink);
}

.diary-page[data-hero="centered"] .diary-summary {
  margin-inline: auto;
  max-width: 36rem;
  font-size: 1.1rem;
  font-family: var(--font-body);
  color: var(--ink-soft);
}

.diary-page[data-hero="centered"] .diary-theme-note {
  margin-inline: auto;
  max-width: 36rem;
  color: var(--muted);
}

.diary-page[data-hero="centered"] .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page[data-hero="centered"] .diary-kicker {
  letter-spacing: 0.28em;
  font-weight: 700;
}

/* Crumbs and kicker get a red underline accent */
.diary-page .diary-crumbs a {
  color: var(--muted);
  letter-spacing: 0.08em;
  font-size: 0.8rem;
}

.diary-page .diary-crumbs a::before {
  content: "← ";
}

.diary-page .diary-crumbs a:hover {
  color: var(--accent);
}

/* Section heads: ticker numbers sit in red squares */
.diary-page .diary-section-head {
  border-bottom: 1px solid var(--rule);
  padding-bottom: 0.75rem;
  margin-bottom: 1.5rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--accent);
  background: rgba(255, 92, 92, 0.12);
  padding: 0.15rem 0.55rem;
  border-radius: 2px;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 3vw, 2.25rem);
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--ink);
}

/* Cards: ticker-tape borders, red edges */
.diary-page .diary-card--banner .diary-card-inner {
  border: 1px solid var(--rule);
  border-top: 3px solid var(--accent);
  background: var(--paper);
  padding: 0;
}

.diary-page .diary-card--banner .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 0.7rem 1rem;
}

.diary-page .diary-card--banner .diary-card-body {
  padding: 1rem 1.1rem 1.25rem;
  color: var(--ink-soft);
}

.diary-page .diary-card--outline .diary-card-inner {
  border: 1px solid var(--rule);
  border-left: 3px solid var(--accent);
  border-radius: 0;
  padding: 1.25rem 1.25rem 1.4rem;
}

.diary-page .diary-card--outline .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--ink);
}

/* Numbered cards: big red index, no box */
.diary-page .diary-card--numbered .diary-card-inner {
  border-top: 1px solid var(--rule);
  padding-top: 1.25rem;
}

.diary-page .diary-card--numbered .diary-card-index {
  font-family: var(--font-ui);
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 0.06em;
}

/* Split cards: a sharp red top border, headline on the left */
.diary-page .diary-card--split .diary-card-inner {
  border-top: 2px solid var(--accent);
  padding-top: 1.25rem;
}

.diary-page .diary-card--split .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1.15;
  color: var(--ink);
}

/* Stat cards: red figure on a raised platform */
.diary-page .diary-card--stat .diary-card-inner {
  border-top: 3px solid var(--accent);
  padding: 1.1rem 0 0.25rem;
}

.diary-page .diary-card--stat .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(2rem, 10cqi, 3rem);
  font-weight: 800;
  letter-spacing: 0.04em;
  color: var(--accent);
}

.diary-page .diary-card--stat .diary-card-title {
  font-family: var(--font-ui);
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-card--stat .diary-card-body {
  color: var(--ink-soft);
}

/* Timeline cards: red dots on a dark rail */
.diary-page .diary-card--timeline .diary-card-inner {
  padding-left: 1.5rem;
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  background: var(--rule);
  width: 1px;
  left: 0.25rem;
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 3px var(--paper);
  width: 0.5rem;
  height: 0.5rem;
  left: 0;
}

.diary-page .diary-card--timeline .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--ink);
}

/* Thread pill: red outline, red text */
.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  padding: 0.15rem 0.6rem;
  border-radius: 2px;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Body text */
.diary-page .diary-prose {
  color: var(--ink-soft);
  font-size: 1.12rem;
  line-height: 1.7;
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom: 1px solid rgba(255, 92, 92, 0.4);
  font-weight: 700;
  font-size: 0.7em;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

/* Lede cards in the mix */
.diary-page .diary-card-lede {
  border-left: 3px solid var(--accent);
  font-family: var(--font-body);
  font-size: 1.25rem;
  line-height: 1.5;
  color: var(--ink);
}

/* Markets: dark panels with red ticks */
.diary-page .diary-markets-label {
  color: var(--muted);
  letter-spacing: 0.16em;
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-left: 2px solid var(--accent);
  font-family: var(--font-ui);
}

.diary-page .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-spark.is-in-down .diary-spark-change,
.diary-page .diary-spark.is-down .diary-spark-change {
  color: var(--accent);
}

/* Footer: red top border */
.diary-page .diary-footer {
  border-top: 1px solid var(--rule);
  font-family: var(--font-ui);
  font-size: 0.82rem;
  color: var(--muted);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* Contents: red numbers, no active-left-border on the sidebar (ticker squares instead) */
.diary-page .diary-toc-link {
  font-family: var(--font-ui);
  font-size: 0.85rem;
  color: var(--muted);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--accent);
  background: rgba(255, 92, 92, 0.12);
  padding: 0.1rem 0.35rem;
  border-radius: 2px;
}

.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  font-family: var(--font-ui);
  font-size: 0.82rem;
  color: var(--muted);
}

.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-bottom:hover {
  color: var(--accent);
}

/* Drop cap: red, square, uppercase */
.diary-page .diary-section:first-child .diary-card--plain:first-child .diary-prose > p:first-of-type::first-letter {
  font-family: var(--font-display);
  font-size: 3.2em;
  font-weight: 800;
  color: var(--accent);
  line-height: 0.9;
  margin-right: 0.12em;
}

/* Sparkline lines: red for down, neutral for up */
.diary-page .diary-spark.is-down .diary-spark-line {
  stroke: var(--accent);
}

.diary-page .diary-spark.is-up .diary-spark-line {
  stroke: var(--muted);
}

/* Add ticker-tape slashes to section headers in a subtle way */
.diary-page .diary-section::before {
  content: "";
  display: block;
  height: 1px;
  background: repeating-linear-gradient(
    90deg,
    var(--rule) 0rem,
    var(--rule) 0.4rem,
    transparent 0.4rem,
    transparent 1rem
  );
  margin-bottom: 2.5rem;
}

.diary-page .diary-section:first-child::before {
  display: none;
}

/* Music cards: keep players truly clean but the surrounding text red-tinted */
.diary-page .diary-card:has(.diary-embed) {
  border: 0;
  background: none;
}

/* Masonry: tighter gaps to keep the page dense */
.diary-page .diary-stories--masonry {
  column-gap: 1.25rem;
}

.diary-page .diary-stories--masonry > .diary-card {
  margin-bottom: 1.25rem;
}

/* Grids: tighter rhythm */
.diary-page .diary-stories {
  gap: 1.25rem;
}

/* Keep the ticker theme on the outlook timeline */
.diary-page .diary-card--timeline .diary-card-body {
  font-size: 1.05rem;
}

/* On wide screens, add a red left rule to the sticky contents */
@media (min-width: 1024px) {
  .diary-page .diary-toc-list {
    border-left: 1px solid var(--rule);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}
